    ALTERNATIVENPRUEFUNG = "Fachplanerische Alternativenprüfung"
    PLANUNGSLEITSAETZE = "Planungsleitsätze"
    RAUMORDNUNG = "Raumordnung"
    BAULEITPLANUNG = "Bauleitplanung"
    GESAMTABWAEGUNG = "Gesamtabwägung"

