class StateLaws(StrEnum):
    LANDESWALDGESTZ = "LwaldG"
    LANDESRAUMORDNUNGSGESETZ = "LplG"
    LANDESEDNKMALSCHUTZGESETZ = "DSchG"
    LANDESJAGDRECHT = "LJagdG"


@dataclass(frozen=True)
class TopicNormSeed:
    jurabk: str
    paragraph_nr: str | None = None
    absatz: str | None = None
    satz: str | None = None
    nummer: str | None = None

    def __post_init__(self) -> None:
        normalized = normalize_paragraph_nr(self.paragraph_nr)
        if normalized != self.paragraph_nr:
            object.__setattr__(self, "paragraph_nr", normalized)


@dataclass(frozen=True)
class SubtopicSeed:
    name: str
    description: str
    show_in_mvp: bool = True
    show_in_ewm: bool = True
    show_in_beschluss: bool = True
    pruefungs_norms: tuple[TopicNormSeed, ...] = ()
    verfahrens_norms: tuple[TopicNormSeed, ...] = ()


@dataclass(frozen=True)
class TopicSeed:
    name: TopicEnum | str
    description: str
    show_in_mvp: bool = True
    show_in_ewm: bool = True
    show_in_beschluss: bool = True
    pruefungs_norms: tuple[TopicNormSeed, ...] = ()
    verfahrens_norms: tuple[TopicNormSeed, ...] = ()
    sub_topics: tuple[SubtopicSeed, ...] = ()


