            name=TopicEnum.NEBENBESTIMMUNGEN,
            show_in_mvp=False,
            description="Nebenbestimmungen (z.B. Auflagen, Bedingungen, Befristungen, Widerrufsvorbehalte, Auflagenvorbehalte) sind einseitige hoheitliche Anordnungen der Behörde, die den Inhalt eines Verwaltungsakts modifizieren oder ergänzen. Nebenbestimmungen werden häufig von Fachbehörden in ihren Stellungnahmen vorgeschlagen . Sie dienen oft dazu, die Genehmigungsfähigkeit des Antrags herzustellen. Häufig wird eine Auflage erteilt, d.h. eine Bestimmung getroffen, durch die dem Begünstigten ein Tun, Dulden oder Unterlassen vorgeschrieben wird.",
