            description="'Entschädigungen' thematisiert u.a., für welche durch das Vorhaben verursachten vermögenswerten Nachteile (z.B. Flächeninanspruchnahme, Wertminderungen, Nutzungsbeeinträchtigungen, baubedingte Schäden, verbleibende Immissionen) nach den einschlägigen Rechtsgrundlagen (bspw. BImSchG) ein Ausgleich in Geld oder in anderer Weise zu leisten ist. Auch Klarstellungen, dass die konkrete Höhe der Entschädigung nicht im Planfeststellungsbeschluss festgelegt wird, sondern in gesonderten Enteignungs-/Entschädigungsverfahren oder durch Vereinbarungen mit dem Vorhabenträger und welche Stellen dafür zuständig sind, fallen hierunter.",
            verfahrens_norms=(TopicNormSeed(jurabk="VwVfG", paragraph_nr="74", absatz="2", satz="3"),),
