            description="Das Thema 'straßenrechtliche Entscheidungen' befasst sich mit der Widmung, Umstufung oder Einziehung neu gebauter oder geänderter Straßen, der Zuordnung der Straßenklasse und der Straßenbaulast, der Aufhebung / Verlegung von vorhandenen Straßen, Wegen, Zufahrten und ggf. deren Anbindung an die neue Straße und ggf. die Übernahe bisheriger Straßen durch einen anderen Straßenbaulastträger.",
            verfahrens_norms=(TopicNormSeed(jurabk="FStrG", paragraph_nr="2"),),
