TOPIC_STATE_GROUPS: dict[TopicEnum, tuple[str, ...]] = {
    TopicEnum.WALDSCHUTZ: (StateLaws.LANDESWALDGESTZ,),
    TopicEnum.FORSTWIRTSCHAFT: (StateLaws.LANDESWALDGESTZ,),
    TopicEnum.RAUMORDNUNG: (StateLaws.LANDESRAUMORDNUNGSGESETZ,),
    TopicEnum.DENKMALSCHUTZ: (StateLaws.LANDESEDNKMALSCHUTZGESETZ,),
    TopicEnum.JAGDRECHT: (StateLaws.LANDESJAGDRECHT,),
}


def _extra_norms_for_topic(topic: TopicSeed, state: GermanState) -> tuple[TopicNormSeed, ...]:
    groups = TOPIC_STATE_GROUPS.get(topic.name, ())
    norms: list[TopicNormSeed] = []

    for group in groups:
        norms.extend(STATE_NORM_GROUPS.get((group, state), ()))

    return tuple(norms)


def _merge_norms(
    base: tuple[TopicNormSeed, ...],
    extra: tuple[TopicNormSeed, ...],
) -> tuple[TopicNormSeed, ...]:
    return tuple(dict.fromkeys((*base, *extra)))


def get_default_topics_for_project_type_name(
    project_type_name: str,
    state: GermanState,
) -> tuple[TopicSeed, ...]:
    topics = DEFAULT_TOPICS_BY_PROJECT_TYPE_NAME.get(project_type_name, ())
    result = []

    for topic in topics:
        extra = _extra_norms_for_topic(topic, state)

        if not extra:
            result.append(topic)
            continue

        result.append(
            replace(
                topic,
                pruefungs_norms=_merge_norms(topic.pruefungs_norms, extra),
            )
        )

    return tuple(result)
